/**
 * Dispatches authenticated GitHub and Origin events to matching agents.
 *
 * Callers must authenticate the delivery before invoking this fan-out. It
 * does not re-check provider signatures.
 *
 * Each agent's `onPullRequest`, `onComment`, and related hooks decide whether
 * to run.
 */
import { dispatchGitHubWebhook, getGitHubChannelOptions, githubChannelWebhookSecret, verifyGitHubWebhookSignature, } from "../channels/github/github-channel.js";
import { dispatchOriginWebhook, getOriginChannelOptions, originIngressExtractPayload, parseOriginWebhookEnvelope, } from "../channels/origin/origin-channel.js";
import { bindLocalIngressSend } from "./local-ingress.js";
/**
 * Build fan-out targets from mounted agent projects that export a github
 * channel created via {@link githubChannel}.
 * @deprecated Deprecated on the package root.
 */
export function collectGitHubTriggerTargets(input) {
    const targets = [];
    for (const mount of input.mounts) {
        for (const channel of mount.channels) {
            const options = getGitHubChannelOptions(channel.definition);
            if (options === undefined) {
                continue;
            }
            targets.push({
                slug: mount.slug,
                options,
                args: mount.buildHandlerArgs(channel.id),
            });
        }
    }
    return targets;
}
/**
 * Build fan-out targets from mounted agent projects that export an origin
 * channel created via {@link originChannel}.
 * @deprecated Deprecated on the package root.
 */
export function collectOriginTriggerTargets(input) {
    const targets = [];
    for (const mount of input.mounts) {
        for (const channel of mount.channels) {
            const options = getOriginChannelOptions(channel.definition);
            if (options === undefined) {
                continue;
            }
            targets.push({
                slug: mount.slug,
                options,
                args: mount.buildHandlerArgs(channel.id),
            });
        }
    }
    return targets;
}
export async function partitionGitHubWebhookTargets(input) {
    const admitted = [];
    const rejected = [];
    for (const target of input.targets) {
        const secret = githubChannelWebhookSecret(target.options);
        if (secret === undefined) {
            admitted.push(target);
            continue;
        }
        const signatureResult = await verifyGitHubWebhookSignature({
            body: input.bodyText,
            signatureHeader: input.signatureHeader,
            secret,
        });
        if (signatureResult === "verified") {
            admitted.push(target);
            continue;
        }
        rejected.push({
            slug: target.slug,
            status: 401,
            body: { ok: false, error: signatureResult },
        });
    }
    return { admitted, rejected };
}
/**
 * Dispatch an agent-serve trigger. GitHub and Origin webhook fan-out.
 * @deprecated Deprecated on the package root.
 */
export async function handleAgentServeTrigger(event) {
    switch (event.type) {
        case "github":
            return handleAgentServeGitHubTrigger(event);
        case "origin":
            return handleAgentServeOriginTrigger(event);
        default: {
            const _ = event;
            throw new Error(`handleAgentServeTrigger: unknown event type: ${String(_)}`);
        }
    }
}
async function handleAgentServeGitHubTrigger(event) {
    if (event.eventName === "ping") {
        return {
            ok: true,
            event: "ping",
            targets: [],
        };
    }
    let payload;
    try {
        payload = JSON.parse(event.bodyText);
    }
    catch {
        return {
            ok: false,
            event: event.eventName,
            targets: [
                {
                    slug: "",
                    status: 400,
                    body: { ok: false, error: "invalid_json" },
                },
            ],
        };
    }
    const targets = [];
    for (const target of event.targets) {
        const args = event.eventName === null
            ? target.args
            : bindLocalIngressSend(target.args, {
                identity: target.options.continuation,
                kind: "github",
                eventType: event.eventName,
                payload,
                ...(event.routeContinuation === undefined
                    ? {}
                    : { routeContinuation: event.routeContinuation }),
            });
        const response = await dispatchGitHubWebhook({
            options: target.options,
            eventName: event.eventName,
            payload,
            deliveryId: event.deliveryId,
            args,
        });
        targets.push(await triggerTargetResult(target.slug, response));
    }
    return {
        ok: true,
        event: event.eventName,
        targets,
    };
}
async function handleAgentServeOriginTrigger(event) {
    let payload;
    try {
        payload = JSON.parse(event.bodyText);
    }
    catch {
        return {
            ok: false,
            event: null,
            targets: [
                {
                    slug: "",
                    status: 400,
                    body: { ok: false, error: "invalid_json" },
                },
            ],
        };
    }
    const envelope = parseOriginWebhookEnvelope(payload);
    if (envelope === null) {
        return {
            ok: false,
            event: null,
            targets: [
                {
                    slug: "",
                    status: 400,
                    body: { ok: false, error: "invalid_origin_payload" },
                },
            ],
        };
    }
    const targets = [];
    for (const target of event.targets) {
        const response = await dispatchOriginWebhook({
            options: target.options,
            envelope,
            args: bindLocalIngressSend(target.args, {
                identity: target.options.continuation,
                kind: "origin",
                eventType: envelope.event.type,
                payload: originIngressExtractPayload(envelope),
                ...(event.routeContinuation === undefined
                    ? {}
                    : { routeContinuation: event.routeContinuation }),
            }),
        });
        targets.push(await triggerTargetResult(target.slug, response));
    }
    return {
        ok: true,
        event: envelope.event.type,
        targets,
    };
}
async function triggerTargetResult(slug, response) {
    let body;
    try {
        body = await response.json();
    }
    catch {
        body = { ok: false, error: "invalid_response_json" };
    }
    return {
        slug,
        status: response.status,
        body,
    };
}
